"""README online-list section — kept current by every `radar run`.

The README's "Latest global remote hackathons" list lives between two HTML
comment markers::

    <!-- ONLINE-LIST:START (auto-generated by `radar run` — do not edit by hand) -->
    **Last fetched:** 2026-10-16 00:14 IST · open: 47 · online: 40 · new: 14
    | Name | Platform | Status | Deadline | Days | Starts | Ends | Prize | Themes |
    <!-- ONLINE-LIST:END -->

``radar run`` replaces the marked block with the fresh ``online.md`` body
(header line + table — the rendered "online lens") right after writing the
data files, so the README always lists the live online hackathons as of the
last fetch, with the exact fetch date/time stamped on the header line (the
data files keep their own ``Last updated`` wording verbatim; the README
relabels it ``Last fetched``).

The README table is a **compact view**: ``slim_table`` keeps only the nine
columns that carry information here (``README_COLUMNS``) — ``Mode`` is always
``Online`` in this section, ``Team``/``Eligibility``/``Cost``/``Also on`` are
empty in practice, and ``Updated`` duplicates the ``Last fetched`` stamp. The
full 15-column table stays in ``data/online.md``.

The markers are the contract: a README without them is left untouched
(warning), never clobbered, and a hand-written README keeps its own text
around the section.
"""

import logging
import re
from pathlib import Path

logger = logging.getLogger(__name__)

#: Section markers. The start marker's whole line is preserved verbatim;
#: everything between the two marker lines is regenerated.
MARKER_START = "<!-- ONLINE-LIST:START"
MARKER_END = "<!-- ONLINE-LIST:END -->"

#: README table columns: source header in ``online.md`` → README header.
#: Ordered — the README table follows this order, not the source order.
README_COLUMNS = (
    ("Name", "Name"),
    ("Platform", "Platform"),
    ("Status", "Status"),
    ("Reg. deadline", "Deadline"),
    ("Days left", "Days"),
    ("Starts", "Starts"),
    ("Ends", "Ends"),
    ("Prize", "Prize"),
    ("Themes", "Themes"),
)

#: Unescaped pipes split table cells; ``\|`` (the renderer's escaping) does not.
_PIPE_RE = re.compile(r"(?<!\\)\|")


def _cells(line: str) -> list[str]:
    """The stripped cells of one markdown table row (split on unescaped pipes)."""
    stripped = line.strip()
    if stripped.startswith("|"):
        stripped = stripped[1:]
    if stripped.endswith("|"):
        stripped = stripped[:-1]
    return [cell.strip() for cell in _PIPE_RE.split(stripped)]


def slim_table(text: str) -> str:
    """PURE: narrow the markdown table in ``text`` to ``README_COLUMNS``.

    Non-table lines pass through untouched; the header row selects the kept
    columns (in ``README_COLUMNS`` order) and relabels them; every data and
    separator row is rewritten with the same selection, cell content
    (including ``\\|`` escaping) preserved verbatim. A table whose headers
    match none of ``README_COLUMNS`` is returned unchanged — never an empty
    table. Text without a table is returned unchanged.
    """
    out: list[str] = []
    header_done = False
    kept: list[int] = []
    for line in text.splitlines():
        if not line.lstrip().startswith("|"):
            out.append(line)
            continue
        cells = _cells(line)
        if not header_done:
            index_by_name = {name: position for position, name in enumerate(cells)}
            if not any(source in index_by_name for source, _ in README_COLUMNS):
                return text  # unrecognized table: never rewrite it
            header_done = True
            kept = [
                index_by_name[source]
                for source, _ in README_COLUMNS
                if source in index_by_name
            ]
            row = [label for source, label in README_COLUMNS if source in index_by_name]
        else:
            row = [cells[position] for position in kept if position < len(cells)]
        out.append("| " + " | ".join(row) + " |")
    if not header_done:
        return text  # no table at all: verbatim, trailing newline included
    result = "\n".join(out)
    if text.endswith("\n") and not result.endswith("\n"):
        result += "\n"
    return result


def section_body(online_md: str) -> str:
    """The ``online.md`` content minus its H1 title and blank edges.

    The ``**Last updated:**`` header is relabeled ``**Last fetched:**`` —
    the README's wording for the last fetch date/time (the data files keep
    their own header verbatim) — and the table is slimmed to
    ``README_COLUMNS`` (see ``slim_table``).
    """
    lines = online_md.splitlines()
    if lines and lines[0].startswith("# "):
        lines = lines[1:]
    while lines and not lines[0].strip():
        lines.pop(0)
    while lines and not lines[-1].strip():
        lines.pop()
    body = "\n".join(lines)
    if body.startswith("**Last updated:**"):
        body = "**Last fetched:**" + body[len("**Last updated:**") :]
    return slim_table(body)


def inject_online_section(readme_text: str, online_md: str) -> str:
    """PURE: replace the marked README section with the fresh online body.

    Returns the text unchanged when either marker is missing or the end
    marker precedes the start (a README without a valid section is never
    clobbered). Deterministic: same inputs → same output.
    """
    start = readme_text.find(MARKER_START)
    end = readme_text.find(MARKER_END)
    if start == -1 or end == -1 or end <= start:
        return readme_text
    start_line_end = readme_text.find("\n", start)
    if start_line_end == -1 or start_line_end > end:
        return readme_text
    return (
        readme_text[: start_line_end + 1]
        + "\n"
        + section_body(online_md)
        + "\n"
        + readme_text[end:]
    )


def update_readme(readme_path: Path, online_md: str) -> bool:
    """Write the injected README when it changes; returns True when written.

    A missing README, or one without the markers, is reported (warning) and
    skipped — the online list is auxiliary, it must never clobber a
    hand-written file.
    """
    if not readme_path.exists():
        logger.warning("README %s not found — online list not updated", readme_path)
        return False
    text = readme_path.read_text(encoding="utf-8")
    updated = inject_online_section(text, online_md)
    if updated == text:
        if MARKER_START not in text or MARKER_END not in text:
            logger.warning(
                "README %s has no ONLINE-LIST markers — online list not updated",
                readme_path,
            )
        return False
    readme_path.write_text(updated, encoding="utf-8")
    return True
